INSERT INTO feature VALUES('model-opening','modules','Opening a model in a block','signature-models','implemented','notable',NULL,'An existential is a model whose sort its type leaves abstract, `p : Model(S)`. `module m = p ;` in a block opens it over the rest of the block as the bind of `return p` at that type, so each sort is fresh at each opening: a seed read at the type the sort hides is refused `TypeMismatch`, two openings of one model are two types, and a block whose type names the sort is refused `DependentBind`. A name no binder or definition declares at a model type is refused `NotAModel`. The `pack [T]`, `package [T]` and `unpack` forms are retired for it.','surface-grammar surface-lowering','corpus/model/packages/packages.gandr corpus/pathological/packages/package-abstraction-leak.gandr corpus/ledger/diagnostics/NotAModel.gandr','corpus/model/packages/packages.gandr',NULL);
